    t.packets.clear();
    afterUnlock = [&]() { d.SetIndices(&ib2); };
    d.SetIndices(&ib);
    check(t.packets.size() == 2 && t.packets[0].data[0] == ib2.id && t.packets[1].data[0] == ib.id);
    Host reordered; for (const auto& p : t.packets) { reordered.process(p); }
    d.SetIndices(&ib2); check(d.lastMatch && reordered.indices != ib2.id);
    // Real two-thread schedule with the state mutex enabled; no data race needed.
    std::atomic<unsigned> phase{0}; t.packets.clear();
    std::thread first([&]() {
      activeTransport = &t;
      afterUnlock = [&]() { phase.store(1); while (phase.load() != 2) { std::this_thread::yield(); } };
      d.SetStreamSource(2, &vb, 0, 16);
    });
    std::thread second([&]() {
      activeTransport = &t;
      while (phase.load() != 1) { std::this_thread::yield(); }
      d.SetStreamSource(2, &vb2, 0, 16); phase.store(2);
    });
    first.join(); second.join();
    Host concurrent; for (const auto& p : t.packets) { concurrent.process(p); }
    check(concurrent.streams[2] == vb.id && *d.m_state.streams[2] == &vb2);
    d.SetStreamSource(2, &vb2, 0, 16); check(d.lastMatch && concurrent.streams[2] != vb2.id);
