#else
template<bool Check> static void benchmark(bool stream, unsigned rate, size_t count) {
  // Inputs and transport storage are allocated before the batch timer.
  std::vector<unsigned> inputs(count);
  unsigned value = 0, accumulator = 0;
  uint64_t expectedMatches = 0;
  for (size_t n = 0; n < count; ++n) {
    accumulator += rate;
    bool same = accumulator >= 10000;
    if (same) { accumulator -= 10000; if (n) { ++expectedMatches; } }
    else { value ^= 1; }
    inputs[n] = value;
  }
  Transport t(count); activeTransport = &t;
  Buffer first(11), second(12);
  Direct3DDevice9Ex_LSS<true, Check> d;
  const auto cpuStart = std::clock();
  const auto start = std::chrono::steady_clock::now();
  for (auto value : inputs) {
    if (stream) { d.SetStreamSource(0, value ? &second : &first, 4, 16); }
    else { d.SetIndices(value ? &second : &first); }
  }
  const auto clientEnd = std::chrono::steady_clock::now();
  const auto cpuEnd = std::clock();
  Host host;
  for (const auto& p : t.packets) { host.process(p); }
  const auto hostEnd = std::chrono::steady_clock::now();
  assert(t.packets.size() == count);
  if constexpr (Check) { assert(d.matches == expectedMatches && d.checks == count); }
  const auto ns = [](auto duration) { return std::chrono::duration<double, std::nano>(duration).count(); };
  std::printf("{\"calls\":%zu,\"commands\":%zu,\"wire_bytes_theoretical\":%zu,\"matches\":%llu,\"client_ns_per_call\":%.4f,\"client_cpu_ns_per_call\":%.4f,\"host_adapter_ns_per_call\":%.4f,\"total_ns_per_call\":%.4f,\"host_final\":%u}\n", count, t.packets.size(), count * (stream ? 32 : 20), static_cast<unsigned long long>(Check ? d.matches : expectedMatches), ns(clientEnd - start) / count, 1e9 * (cpuEnd - cpuStart) / CLOCKS_PER_SEC / count, ns(hostEnd - clientEnd) / count, ns(hostEnd - start) / count, stream ? host.streams[0] : host.indices);
}
int main(int argc, char** argv) {
  if (argc != 5) { return 2; }
  const bool stream = std::string(argv[2]) == "stream";
  const auto rate = static_cast<unsigned>(std::stoul(argv[3]));
  const auto count = std::stoull(argv[4]);
  if (argv[1][0] == 'A') { benchmark<false>(stream, rate, count); }
  else { benchmark<true>(stream, rate, count); }
}
